class AsyncEventBus {
  constructor() {
    this.subscribers = new Map();
  }

  subscribe(event, callback) {
    if (!this.subscribers.has(event)) this.subscribers.set(event, new Set());
    this.subscribers.get(event).add(callback);
    return () => this.subscribers.get(event).delete(callback);
  }

  async publish(event, data) {
    if (!this.subscribers.has(event)) return [];
    const callbacks = Array.from(this.subscribers.get(event));
    const promises = callbacks.map(cb => Promise.resolve().then(() => cb(data)));
    return Promise.all(promises);
  }
}

function render(vnode) {
  if (typeof vnode === 'string' || typeof vnode === 'number') {
    return document.createTextNode(String(vnode));
  }

  const el = document.createElement(vnode.type);

  if (vnode.props) {
    Object.entries(vnode.props).forEach(([key, val]) => {
      if (key.startsWith('on')) {
        el.addEventListener(key.slice(2).toLowerCase(), val);
      } else {
        el.setAttribute(key, val);
      }
    });
  }

  if (vnode.children) {
    vnode.children.forEach(child => el.appendChild(render(child)));
  }

  return el;
}

