  }
  return childPatches;
}

class PriorityAsyncQueue {
  constructor(concurrency = 2) {
    this.concurrency = concurrency;
    this.running = 0;
    this.heap = [];
  }

  enqueue(task, priority = 0) {
    return new Promise((resolve, reject) => {
      this.heap.push({ task, priority, resolve, reject });
      this.heap.sort((a, b) => b.priority - a.priority);
      this.processNext();
    });
  }

  processNext() {
    if (this.running >= this.concurrency || this.heap.length === 0) return;

    const { task, resolve, reject } = this.heap.shift();
    this.running++;

    Promise.resolve(task())
      .then(resolve)
      .catch(reject)
      .finally(() => {
        this.running--;
        this.processNext();
      });
  }
}

class DataPipeline {
  constructor() {
    this.transforms = [];
  }

  use(transformFn) {
    this.transforms.push(transformFn);
    return this;
  }

  async execute(sourceDataStream) {
    const results = [];
    for (let chunk of sourceDataStream) {
      let currentData = chunk;
      let skipped = false;

      for (let transform of this.transforms) {
        currentData = await transform(currentData);
        if (currentData === null || currentData === undefined) {
          skipped = true;
          break;
        }
      }

      if (!skipped) {
        results.push(currentData);
      }
    }
    return results;
  }
}

