function mergeTwoLists(l1, l2) {
  const dummy = { val: 0, next: null };
  let tail = dummy;

  while (l1 !== null && l2 !== null) {
    if (l1.val < l2.val) {
      tail.next = l1;
      l1 = l1.next;
    } else {
      tail.next = l2;
      l2 = l2.next;
